/* Original schematic strategy landscape. Positions are illustrative, not geographic. */
function desktopAtlasLayout(count,cities,width,height){const columns=Math.max(3,Math.ceil(Math.sqrt(Math.max(3,count)*1.7))),rows=Math.ceil(Math.max(3,count)/columns);return {desktop:true,columns,rows,width:Math.max(width,cities?0:columns*320+160),height:Math.max(height,cities?0:rows*270+180)}}
function desktopAtlasPoint(i,count,cities){if(cities)return [[.25,.29],[.51,.48],[.78,.68]][i];if(count<=3)return [[.25,.38],[.52,.63],[.79,.32]][i];const cols=Math.ceil(Math.sqrt(count*1.7)),rows=Math.ceil(count/cols);return [.14+(i%cols)*.72/Math.max(1,cols-1),.30+Math.floor(i/cols)*.45/Math.max(1,rows-1)]}
function desktopAtlasTerrain(){
 const tree=(x,y,k)=>`<g transform="translate(${x} ${y}) scale(${k})"><ellipse cx="0" cy="23" rx="14" ry="6" fill="#36573a" opacity=".17"/><path d="M-2 2h5v23h-5Z" fill="#8f7449"/><path d="M0-37L-19-3h9l-17 19h54L10-3h9Z" fill="#467c58"/><path d="M0-37v53h27L10-3h9Z" fill="#37694c"/><path d="M0-27L-11-7h7l-13 16h17Z" fill="#72a46b" opacity=".6"/></g>`;
 const groves=[[60,70,200,100],[950,60,210,110],[40,550,200,160],[1050,560,180,160],[530,40,150,65]];
 const trees=groves.map(([x,y,w,h],g)=>Array.from({length:30},(_,i)=>tree(x+(i*67+g*13)%w,y+(i*37+g*29)%h,.7+(i%4)*.13)).join('')).join('');
 return `<svg class="desktop-atlas-terrain" viewBox="0 0 1440 900" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="atlas-land" x2="1" y2="1"><stop stop-color="#bfd38a"/><stop offset=".5" stop-color="#a9c779"/><stop offset="1" stop-color="#8caf6d"/></linearGradient><linearGradient id="atlas-water" x2=".3" y2="1"><stop stop-color="#78b8b4"/><stop offset="1" stop-color="#519b9e"/></linearGradient><pattern id="atlas-crops" width="14" height="14" patternUnits="userSpaceOnUse" patternTransform="rotate(-18)"><path d="M0 0v14" stroke="#96af60" stroke-width="7"/></pattern><pattern id="atlas-lawn" width="95" height="90" patternUnits="userSpaceOnUse"><path d="m12 25 2-5 3 5m60 39 2-4 2 4" fill="none" stroke="#77964e" opacity=".3"/><circle cx="39" cy="53" r="2" fill="#fff4c0" opacity=".6"/></pattern></defs><path fill="url(#atlas-land)" d="M0 0h1440v900H0Z"/><path fill="#729f6450" d="M0 0h380q-30 130-250 150L0 300ZM1440 450q-250 30-300 280l30 170h270Z"/><path fill="#d2db9560" d="M400 0q-80 170 180 200t480-180ZM0 430q250-120 380 100T100 900H0Z"/><path d="M850-70C620 95 1050 245 820 350S450 460 700 615 510 760 490 970" fill="none" stroke="#769964" stroke-width="100"/><path d="M850-70C620 95 1050 245 820 350S450 460 700 615 510 760 490 970" fill="none" stroke="#c6d5ab" stroke-width="86"/><path d="M850-70C620 95 1050 245 820 350S450 460 700 615 510 760 490 970" fill="none" stroke="url(#atlas-water)" stroke-width="66"/><path d="M845-70C620 95 1050 245 820 350S450 460 700 615 510 760 490 970" fill="none" class="atlas-water-ripples" stroke="#d5eee0" stroke-width="2" stroke-dasharray="28 64 55 140" opacity=".7"/><path d="M-70 320Q260 130 460 350T820 480 1500 680M300-50Q140 160 460 350T610 950" fill="none" stroke="#9b9f6c" stroke-width="25" opacity=".6"/><path d="M-70 320Q260 130 460 350T820 480 1500 680M300-50Q140 160 460 350T610 950" fill="none" stroke="#e9dab0" stroke-width="18"/><path d="M1000-20Q1060 200 820 480T1250 950" fill="none" stroke="#eadcb6" stroke-width="11"/><path d="M0 640Q160 490 370 630M1150 80l140 250" fill="none" stroke="#dfd3a3" stroke-width="9"/><path d="M595 470l75 4" stroke="#857550" stroke-width="37"/><path d="M595 470l75 4" stroke="#e1c896" stroke-width="28"/><path d="M600 461l67 4m-68 15 67 4" stroke="#f9e4bc" stroke-width="3"/><path d="m1000 720 165 50-54 118-167-43Z M80 430l190-20 21 105-174 34Z M1180 260l180 30-12 104-190-22Z" fill="#c4cb81" stroke="#d6d79a" stroke-width="6"/><path d="m1000 720 165 50-54 118-167-43Z M80 430l190-20 21 105-174 34Z M1180 260l180 30-12 104-190-22Z" fill="url(#atlas-crops)" opacity=".8"/><path fill="url(#atlas-lawn)" d="M0 0h1440v900H0Z"/>${trees}<g fill="#f9f6dc" opacity=".6"><path d="M430 80q8-9 16 0q8-9 16 0q-8-4-16 3q-8-7-16-3M1020 530q8-9 16 0q8-9 16 0q-8-4-16 3q-8-7-16-3"/></g></svg>`;
}
function desktopCityArt(city){const roof=city==='moscow'?'#ba6f54':city==='petersburg'?'#668e87':'#d59c59';return `<svg class="desktop-city-skyline" viewBox="0 0 330 220" aria-hidden="true"><ellipse cx="165" cy="184" rx="145" ry="24" fill="#66874e" opacity=".25"/><path d="M23 160l144-48 142 49-139 47Z" fill="#e3d4a6"/><g stroke="#dccda2" stroke-width="2"><path d="M45 111l41-17 41 17v62l-41 17-41-17Z" fill="#f1dfa9"/><path d="M45 111l41-30 41 30-41 17Z" fill="${roof}"/><path d="M207 106l35-15 40 16v64l-38 15-37-16Z" fill="#e9d5a1"/><path d="M202 107l40-31 45 31-42 15Z" fill="${roof}"/><path d="M112 97l53-21 49 22v85l-50 20-52-20Z" fill="#f7e8bd"/><path d="M112 97l53-29 49 30-50 19Z" fill="${roof}"/><path d="M156 80V31h18v49" fill="#f1ddac"/><path d="M150 35l15-27 16 27Z" fill="${roof}"/></g><g fill="#78948d"><path d="M60 128h12v18H60Zm35 0h12v18H95Zm32-2h13v20h-13Zm26 8h14v20h-14Zm27-8h13v20h-13Zm41 0h12v18h-12Zm30 0h12v18h-12Z"/></g><path d="M155 179v-16q10-18 20 0v16" fill="#8b8061"/><g fill="#6e9a57"><ellipse cx="36" cy="170" rx="20" ry="12"/><ellipse cx="290" cy="174" rx="19" ry="12"/></g><path d="M166 9v-8" stroke="#a78951" stroke-width="3"/></svg>`}
farmViews.add(()=>{
 if(!matchMedia('(min-width:1000px)').matches||!document.body.classList.contains('atlas-screen'))return;
 const map=document.querySelector('.atlas-camera .discovery-map');if(!map)return;const cities=location.hash==='#farms',pins=[...map.querySelectorAll('.discovery-pin')];
 map.classList.add('desktop-world-map');map.querySelectorAll('.discovery-terrain,.discovery-trees').forEach(e=>e.remove());map.insertAdjacentHTML('afterbegin',desktopAtlasTerrain());
 pins.forEach((pin,i)=>{const point=desktopAtlasPoint(i,pins.length,cities);pin.style.left=point[0]*100+'%';pin.style.top=point[1]*100+'%';if(cities){pin.querySelector('.pin-village').innerHTML=desktopCityArt(pin.hash.slice(7))}else{const house=pin.querySelector('.map-farm-house');if(house)house.src='art/house.svg'}});
 const hud=document.querySelector('.atlas-camera-hud>div');if(hud)hud.insertAdjacentHTML('afterbegin','<span class="desktop-atlas-eyebrow">FARM–OFF · ОТКРЫВАЙТЕ НОВОЕ</span>');
});
let desktopAtlasResize=0;addEventListener('resize',()=>{clearTimeout(desktopAtlasResize);desktopAtlasResize=setTimeout(()=>{if(!modal.open&&document.body.classList.contains('atlas-screen'))render()},180)});
